$ec_lang['ip_q_supply']='Portata di alimentazione percorso prova, Q<sub>supply</sub> <span title="Portata che entra solo nel percorso di prova modellato, non nell\'intera zona/sistema — vedere Q_zone nella sezione Progetto Applicazione per il totale di sistema." class="ec-tip">?</span>';
